from ...config import ENBConfig

from .base_cl_tool import BaseClToolInterface


class BtsOperationInterface(BaseClToolInterface):
    """Keywords related to the whole BTS."""

    def block_bts(self, timeout='15min', **kwargs):
        """
        Block BTS.

        :return: Path(s) of collected file(s).
        :rtype: list
        """
        alias = kwargs.get('alias')
        alias = alias.strip() if alias else None
        timeout = self._convert_to_secs(timeout)
        config = self.command_store.get(alias).get_config()
        ne = kwargs.get('ne', config.trs_ip).strip()
        pw = kwargs.get('pw', config.pw).strip()
        params = {'ne': ne, 'pw': pw, 'timeout': timeout}
        nolog = config.nolog if kwargs.get('nolog') is None else kwargs.get('nolog')
        flags = ['nolog'] if nolog else []
        return self._execute_cl_tool_operation(alias=alias, timeout=timeout,
                                               operation='block', params=params, trs_ip=ne, flags=flags)

    def unblock_bts(self, timeout='15min', **kwargs):
        """
        Unblock BTS.

        :return: Path(s) of collected file(s).
        :rtype: list
        """
        alias = kwargs.get('alias')
        alias = alias.strip() if alias else None
        timeout = self._convert_to_secs(timeout)
        config = self.command_store.get(alias).get_config()
        ne = kwargs.get('ne', config.trs_ip).strip()
        pw = kwargs.get('pw', config.pw).strip()
        params = {'ne': ne, 'pw': pw, 'timeout': timeout}
        nolog = config.nolog if kwargs.get('nolog') is None else kwargs.get('nolog')
        flags = ['nolog'] if nolog else []
        return self._execute_cl_tool_operation(alias=alias, timeout=timeout,
                                               operation='unblock', params=params, trs_ip=ne, flags=flags)

    def reset_bts(self, coverage='site', timeout='15min', waitforreset=False, **kwargs):
        """
        Reset BTS.

        :param string coverage: Either bs or site, default is site.
        :param boolean waitforreset: Adds waitforreset flag when building reset command line operation.

        :return: Path(s) of collected file(s).
        :rtype: list
        """
        alias = kwargs.get('alias')
        alias = alias.strip() if alias else None
        timeout = self._convert_to_secs(timeout)
        config = self.command_store.get(alias).get_config()
        ne = kwargs.get('ne', config.trs_ip).strip()
        pw = kwargs.get('pw', config.pw).strip()
        params = {'ne': ne, 'pw': pw, 'timeout': timeout, 'resetCoverage': coverage}
        nolog = config.nolog if kwargs.get('nolog') is None else kwargs.get('nolog')
        flags = ['nolog'] if nolog else []
        if waitforreset:
            flags.append('waitforreset')
        return self._execute_cl_tool_operation(alias=alias, timeout=timeout, operation='reset', params=params,
                                               trs_ip=ne, flags=flags)

    def reset_bts_with_handover(self, coverage='site', timeout='15min', waitforreset=False, **kwargs):
        """
        Reset BTS and handover resources.

        :param string coverage: Either bs or site, default is site.
        :param boolean waitforreset: Adds waitforreset flag when building reset command line operation.

        :return: Path(s) of collected file(s).
        :rtype: list
        """
        alias = kwargs.get('alias')
        alias = alias.strip() if alias else None
        timeout = self._convert_to_secs(timeout)
        config = self.command_store.get(alias).get_config()
        ne = kwargs.get('ne', config.trs_ip).strip()
        pw = kwargs.get('pw', config.pw).strip()
        params = {'ne': ne, 'pw': pw, 'timeout': timeout, 'resetCoverage': coverage}
        nolog = config.nolog if kwargs.get('nolog') is None else kwargs.get('nolog')
        flags = ['handover']
        if waitforreset:
            flags.append('waitforreset')
        if nolog:
            flags.append('nolog')
        return self._execute_cl_tool_operation(alias=alias, timeout=timeout, operation='reset', params=params, trs_ip=ne, flags=flags)

    def enter_test_dedicated_state(self, timeout='15min', keepconn=None, **kwargs):
        """
        Resets BTS into test dedicated state and waits for the reset to be finished.

        :param keepconn: Keep tool connected for a number of seconds after operation

        :return: Path(s) of collected file(s).
        :rtype: list
        """
        alias = kwargs.get('alias')
        alias = alias.strip() if alias else None
        timeout = self._convert_to_secs(timeout)
        config = self.command_store.get(alias).get_config()
        ne = kwargs.get('ne', config.trs_ip).strip()
        pw = kwargs.get('pw', config.pw).strip()
        params = {'ne': ne, 'pw': pw, 'timeout': timeout, 'keepconn': keepconn}
        nolog = config.nolog if kwargs.get('nolog') is None else kwargs.get('nolog')
        flags = ['teststate', 'waitforreset']
        if nolog:
            flags.append('nolog')
        return self._execute_cl_tool_operation(alias=alias, timeout=timeout, operation='reset', params=params, trs_ip=ne, flags=flags)
